// Sheet rows -> catalog rows. Empty cells become empty fields ON PURPOSE: an empty
// field is a fact Maya does not have, and she will say she'll check rather than invent it.
// That is the whole point of the catalog, so never substitute a default here.
const split = v => String(v || '').split(/[|\n]/).map(s => s.trim()).filter(Boolean);
const rows = $input.all().map(i => i.json).filter(r => String(r.id || '').trim());

if (!rows.length) {
  // Refuse locally too, so a mis-shared sheet never even reaches the server.
  throw new Error('Products tab has no rows with an id — refusing to sync an empty catalog');
}

const products = rows.map(r => ({
  id: String(r.id).trim(),
  name_he: r.name_he || '',
  name_en: r.name_en || '',
  price: r.price || '',
  old_price: r.old_price || '',
  price_he: r.price_he || '',
  old_price_he: r.old_price_he || '',
  stock_note: r.stock_note || '',
  delivery_note: r.delivery_note || '',
  bullets: split(r.bullets),
  bullets_he: r.bullets_he || '',
  badge_he: r.badge_he || '',
  image_url: r.image_url || '',
  forbidden_claims: split(r.forbidden_claims),
}));

return [{ json: { products, source: 'google-sheet ' + new Date().toISOString() } }];
